#pragma once
// ---------------------------------------------------------------------------
//  globals.h - identity + server + logging configuration for Tank Monitor Device Model-1 v1
//
//  Generated by FirmwareManager for model TMM1V1 on 2026-11-09.
//  Everything model-specific lives here; the OTA and logging modules only read
//  these macros, so they can be dropped into any other sketch unchanged.
//
//  Before the first USB flash:
//    1. Tools -> Partition Scheme: one WITH an OTA slot, e.g.
//       "Minimal SPIFFS (1.9MB APP with OTA)" or "Default 4MB with spiffs".
//    2. Register this board in FirmwareManager -> Devices with its Wi-Fi MAC
//       (printed on Serial at boot) under model TMM1V1.
//    3. Bump FW_VERSION for every build you upload, and upload it with the
//       SAME version number in FirmwareManager -> Firmware.
// ---------------------------------------------------------------------------
#include <Arduino.h>

// --- Identity ----------------------------------------------------------------
#define MODEL_NUMBER   "TMM1V1"      // = FirmwareManager model number
#define DEVICE_NAME    "Tank Monitor Device Model-1 v1"
#define FW_VERSION     "1.0.0"                 // bump on every release build
#define DEVICE_HOSTNAME "tank-monitor-device-model-1-v1"         // mDNS / DHCP host name
#define SETUP_AP_SSID  "TMM1V1-SETUP"     // Wi-Fi setup portal (first boot)
#define SETUP_AP_PASSWORD ""                   // "" = open portal, or >= 8 chars

// --- FirmwareManager backend ----------------------------------------------------
// OTA + logging try the PRIMARY server first. Only if it is unreachable (or
// the update download fails) do they use the FALLBACK (e.g. a LAN backend).
#define FM_PRIMARY_BASE_URL   "https://firmwaremanager.onrender.com"   // scheme + host, no trailing slash
#define FM_FALLBACK_HOST      "192.168.100.100"      // "" = no fallback, e.g. "192.168.1.50"
#define FM_FALLBACK_PORT      8080        // 443 = https, anything else = http
#define FM_PRIMARY_TIMEOUT_MS  20000   // hosted (Render) instances can take a while to wake
#define FM_FALLBACK_TIMEOUT_MS 8000

// --- OTA updates ---------------------------------------------------------------
#define OTA_CHECK_ON_BOOT      1                          // check once Wi-Fi is up
#define OTA_CHECK_INTERVAL_MS  (6UL * 60UL * 60UL * 1000UL) // then every 6 h (0 = never)
#define OTA_RETRY_INTERVAL_MS  (30UL * 60UL * 1000UL)      // after a failed check

// --- Remote logging (MQTT over WebSocket, broker built into FirmwareManager) ---
// The broker is derived from the backend URLs above (https -> wss://host/mqtt,
// http -> ws://host:port/mqtt). Set MQTT_BROKER_URI to pin a single broker.
#define MQTT_BROKER_URI   ""
#define MQTT_USERNAME     "firmwaremanager"   // = server MQTT_USERNAME
#define MQTT_PASSWORD     "change-me"   // = server MQTT_PASSWORD

// Levels are bitmasks: 0x01 error | 0x02 warn | 0x04 info | 0x08 debug.
// These are only the FIRST-BOOT defaults. After that the FirmwareManager
// console is the only authority (Devices -> Logging): it sends the exact set
// of enabled levels per channel, the device stores it in NVS, and lines of a
// disabled level are dropped before they are even formatted. DEBUG is never
// sent to the server unless it is ticked in the console.
#define LOG_REMOTE_LEVELS_DEFAULT  0x07   // console: error + warn + info
#define LOG_SERIAL_LEVELS_DEFAULT  0x0F   // USB serial: everything
// Compile-time ceiling (0 silent .. 4 debug): calls above it compile out.
#define LOG_LEVEL                  4

#define REMOTE_LOG_LINE_MAX        256          // bytes per line (server max 1024)
#define REMOTE_LOG_BATCH_BYTES     1024         // max payload of one MQTT publish
#define REMOTE_LOG_BUFFER_BYTES    (8 * 1024)   // backlog while offline (PSRAM if present)
#define REMOTE_LOG_FLUSH_MS        2000         // max delay before a partial batch is sent
#define REMOTE_LOG_RETRY_MS        5000         // esp-mqtt reconnect back-off
#define REMOTE_LOG_WATCHDOG_RESTART 1           // reboot after 10 min offline with Wi-Fi up
#define REMOTE_LOG_FALLBACK_MS     60000UL      // switch broker if the current one never connects
#define REMOTE_LOG_PREFER_RETRY_MS (10UL * 60UL * 1000UL) // retry the primary while on fallback

// --- FreeRTOS tasks ------------------------------------------------------------
#define TASK_REMOTE_LOG_CORE   tskNO_AFFINITY
#define TASK_REMOTE_LOG_PRIO   1
#define TASK_REMOTE_LOG_STACK  4096
#define TASK_MQTT_PRIO         1
#define TASK_MQTT_STACK        6144

// --- Wi-Fi ---------------------------------------------------------------------
#define WIFI_CONNECT_TIMEOUT_MS    15000UL
#define WIFI_PORTAL_TIMEOUT_MS     180000UL   // portal after a FAILED saved network; first boot has no limit
#define WIFI_RECONNECT_INTERVAL_MS 10000UL
// Hold this button while powering on to reopen the setup portal (change
// networks / clear credentials left by older firmware). -1 = no button.
// Default: the BOOT button (GPIO9 on ESP32-C3/C6, GPIO0 on ESP32/S2/S3).
#if defined(CONFIG_IDF_TARGET_ESP32C3) || defined(CONFIG_IDF_TARGET_ESP32C6)
#define SETUP_BUTTON_PIN 9
#else
#define SETUP_BUTTON_PIN 0
#endif
// 1 = cap Wi-Fi TX power at 8.5 dBm. Fixes "hotspot not visible / won't
// connect" on many cheap ESP32-C3 boards (e.g. C3 Super Mini).
#define WIFI_TX_POWER_LIMIT 0

